fn exp2_edges() {
    let mut bad = std::vec::Vec::new();
    for &(x, r) in EXP2 {
        judge(&mut bad, &std::format!("exp2({:#018x})", x), exp2(f64::from_bits(x)), r, false);
    }
    report("exp2", &bad, EXP2.len());
}

